INSERT INTO `announcements` (`id`, `title`, `body`, `type`, `audience`, `image`, `status`, `scheduled_at`, `published_at`, `created_at`) VALUES (4,'Fiesta','Join us in celebrating our annual Fiesta! Come and enjoy food, music, traditions, and fun with the community. See you there! 🎊','event','All Users',NULL,'live',NULL,'2026-09-09 07:43:30','2026-09-09 05:43:30');
INSERT INTO `about_sections` (`section_id`, `title`, `icon_key`, `image`, `body`, `sort_order`, `created_at`) VALUES (6,'History','history',NULL,'Long before it carried its present name, the land now known as Malvar was called Luta — a name tied to local legend and the oral histories passed down through Batangas. According to accounts recorded by the historian Ferdinand Blumentritt, the area\'s roots trace back to around 1300 AD, when Datu Puti and his followers, having fled the rule of Sultan Makatunao of Borneo, settled across what is now Batangas province. Their descendants went on to populate parts of Laguna, Cavite, the Bicol region, and this stretch of land then known as Luta — originally a barrio under the municipality of Lipa.\n\nAs Luta grew, its boundaries expanded to include the barrios of Payapa, Kalikangan, San Gallo, and Bilukaw — communities that would later split further into San Fernando, Santiago, Bagong Pook, San Andres, and San Juan as the population grew and organized.\n\nLocal leaders and residents, organized under the group Samahang Mag-aararo, petitioned for Luta\'s independence from Lipa, with the support of then-Secretary of the Interior Teodoro M. Kalaw. Their efforts succeeded on December 16, 1918, when Acting Governor-General Charles B. Yeater proclaimed Luta an independent municipality. The town was formally inaugurated on January 10, 1919 — and renamed Malvar, in honor of General Miguel Malvar, the Batangueño revolutionary leader remembered as the last Filipino general to surrender to American forces during the Philippine-American War.',1,'2026-08-30 14:39:27'),(7,'Geography','geography',NULL,'Malvar sits in the CALABARZON region, nestled between the City of Tanauan to the north and the City of Lipa to the south, within Batangas\' 3rd congressional district. The municipality spans roughly 33 square kilometers and is organized into 15 barangays, with elevations ranging from about 24 to 354 meters above sea level.\n\nIts location along the President J.P. Laurel Highway and its proximity to the Southern Tagalog Arterial Road (STAR Tollway) make Malvar an easy stop for travelers coming from Metro Manila — typically reachable within one and a half to two hours by road.',2,'2026-08-30 14:39:27'),(8,'Economy & Industry','economy',NULL,'Malvar has grown into one of Batangas\' more dynamic economic centers, anchored by the Light Industry & Science Park IV (LISP IV) — a roughly 170-hectare PEZA-registered industrial zone developed by the Science Park of the Philippines. The town is also part of the larger LIMA Estate, a mixed-use economic zone shared with Lipa that spans over 1,000 hectares and hosts hundreds of manufacturing, logistics, and technology locators.\n\nAlongside its industrial growth, agriculture remains part of Malvar\'s identity. Coconut and sugarcane are among the province\'s most widely cultivated crops, and Malvar has been part of local initiatives promoting organic farming — efforts that have earned the area recognition as an emerging \"Organic Capital\" within Batangas, supporting farmers\' associations and small agri-tourism ventures alongside its industrial parks.',3,'2026-08-30 14:39:27'),(9,'Culture & Festivals','culture',NULL,'At the heart of Malvar\'s community life is the San Juan Bautista Parish Church, a longstanding landmark that continues to anchor much of the town\'s religious and civic gatherings. Each year, the Malvar Town Fiesta brings the community together with parades, cultural performances, and local cuisine — a celebration that reflects the same spirit of cooperation that helped the town win its independence back in 1918.\n\nThe Malvar Municipal Hall itself stands as a marker of that history, reflecting decades of local governance rooted in the town\'s founding generation.',4,'2026-08-30 14:39:27'),(10,'Nature & Attractions','nature',NULL,'Despite its industrial growth, Malvar keeps close ties to nature. Calejon Falls in Barangay San Gregorio is among the town\'s best-known natural spots — a set of four major waterfalls (plus two smaller ones) reached by a descent of roughly 300 steps, popular with visitors looking to cool off in its clear waters.\n\nThe town also lies close to Mount Malarayat, offering opportunities for hiking and scenic views over the surrounding Batangas countryside — a reminder that Malvar\'s character is shaped as much by its landscapes as by its factories and fiestas.',5,'2026-08-30 14:39:27');
